    let pdf = polars::prelude::DataFrame::new(
        n,
        vec![
            polars::prelude::Column::new("a".into(), (0..n as i64).collect::<Vec<_>>()),
            polars::prelude::Column::new("b".into(), vec!["x"; n]),
        ],
    )
    .unwrap();
    let mut metas = vec![
        ColumnMeta::new("a".to_string()),
        ColumnMeta::new("b".to_string()),
    ];
